package vn.rtr.aeris.operator01;
import java.util.*;
public final class UiPump98Test{
 static int checks;static void yes(boolean b){if(!b)throw new AssertionError("PUMP_CHECK_"+checks);checks++;}
 static class H{List<Runnable>work=new ArrayList<>(),callbacks=new ArrayList<>();List<List<String>>batches=new ArrayList<>();List<String>errors=new ArrayList<>();boolean throwsEval;UiPump98 p=new UiPump98(work::add,(batch,done)->{if(throwsEval)throw new Exception("INJECTED");batches.add(new ArrayList<>(batch));callbacks.add(done);},errors::add);void flush(){work.remove(0).run();}}
 public static void main(String[]a){H h=new H();for(int i=0;i<20;i++)h.p.enqueue("e"+i);yes(h.work.size()==1);h.flush();yes(h.batches.get(0).size()==8&&h.p.outstanding()==20);yes(h.work.isEmpty());h.p.enqueue("e20");yes(h.work.isEmpty());h.callbacks.get(0).run();yes(h.p.outstanding()==13&&h.work.size()==1);h.callbacks.get(0).run();yes(h.p.outstanding()==13&&h.work.size()==1);h.flush();h.callbacks.get(1).run();h.flush();h.callbacks.get(2).run();List<String>all=new ArrayList<>();for(List<String>b:h.batches)all.addAll(b);List<String>expect=new ArrayList<>();for(int i=0;i<21;i++)expect.add("e"+i);yes(all.equals(expect)&&h.p.outstanding()==0);yes(h.errors.isEmpty());H cap=new H();for(int i=0;i<64;i++)cap.p.enqueue("x");yes(!cap.p.failed()&&cap.p.outstanding()==64);cap.p.enqueue("65");yes(cap.p.failed()&&cap.errors.size()==1);cap.p.enqueue("66");cap.flush();yes(cap.batches.isEmpty()&&cap.errors.size()==1);H eval=new H();eval.throwsEval=true;eval.p.enqueue("x");eval.flush();yes(eval.p.failed()&&eval.errors.size()==1&&eval.work.isEmpty());H chars=new H();chars.p.enqueue(String.join("",Collections.nCopies(16385,"a")));yes(chars.p.failed()&&chars.errors.size()==1);H old=new H();old.p.enqueue("a");old.flush();old.callbacks.get(0).run();old.p.enqueue("b");old.flush();old.callbacks.get(0).run();yes(old.p.outstanding()==1);old.callbacks.get(1).run();yes(old.p.outstanding()==0);System.out.println("{\"status\":\"PASS\",\"checks\":"+checks+",\"scope\":\"Bounded FIFO exact-once UI batching, scheduling/failure injection; host JVM\"}");}
}
